using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "TutorialSetup", menuName = "Data/BattleSceneSetups/TutorialSetup", order = 0)]
public class TutorialSetup : BattleSceneSetup
{
	[Header("Tutorial Handler")]
	[SerializeField]
	private GameObject tutorialHandlerPrefab;

	[Header("Tutorial Battle")]
	[SerializeField]
	private BattleCorruptedAnimals currentBattle;

	[SerializeField]
	private CorruptedAnimalData corruptedAntiquarianCorruptedAnimalData;

	[SerializeField]
	private VoidEvent OnPopulateEnemies;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private TransformReference singleEnemyTransformReference;

	[SerializeField]
	private CorruptedAnimalData strongerCorruptedAntiquarian;

	[SerializeField]
	private PlayerTurnTutorial playerTurnTutorial;

	[Header("Tutorial Dice")]
	[SerializeField]
	private List<InventoryItem> tutorialDiceInventoryItems = new List<InventoryItem>();

	[SerializeField]
	private List<InventoryItem> tutorialDiceToDrawOnFirstTurnInventoryItems = new List<InventoryItem>();

	[SerializeField]
	private List<InventoryItem> tutorialDiceSecondBattleInventoryItems = new List<InventoryItem>();

	[SerializeField]
	private List<InventoryItem> tutorialDiceToDrawOnFirstTurnSecondBattleInventoryItems = new List<InventoryItem>();

	[SerializeField]
	private Dice nonCorruptTutorialDieForDrawFirstTurnSecondBattle;

	[SerializeField]
	private Dice areaCorruptTutorialDieForLastHandPositionSecondBattle;

	[Header("Tutorial Virtue")]
	[SerializeField]
	private Rune[] tutorialRunes = new Rune[0];

	[Header("Fake Reward")]
	[SerializeField]
	private ClearingReward tutorialFakeClearingReward;

	private Vector3 singleEnemyPosition => singleEnemyTransformReference.value.position;

	public CorruptedAnimalData StrongerCorruptedAntiquarian => strongerCorruptedAntiquarian;

	public List<InventoryItem> TutorialDiceToDrawOnFirstTurnInventoryItems => tutorialDiceToDrawOnFirstTurnInventoryItems;

	public List<InventoryItem> TutorialDiceToDrawOnFirstTurnSecondBattleInventoryItems => tutorialDiceToDrawOnFirstTurnSecondBattleInventoryItems;

	public Dice NonCorruptTutorialDieForDrawFirstTurnSecondBattle => nonCorruptTutorialDieForDrawFirstTurnSecondBattle;

	public Dice AreaCorruptTutorialDieForLastHandPositionSecondBattle => areaCorruptTutorialDieForLastHandPositionSecondBattle;

	public Rune[] TutorialRunes => tutorialRunes;

	public override void SetupScene()
	{
		mapHandler.SetClearingReward(tutorialFakeClearingReward, goToEndOfBattleState: false);
		base.SetupScene();
		Object.Instantiate(tutorialHandlerPrefab);
		SetupCorruptedAntiquarian();
		ReferenceSingleton<CoroutineHandler>.Instance.Run(SetupSceneCoroutine());
		ReferenceSingleton<TurnManager>.Instance.SetPlayerTurnTutorial(playerTurnTutorial);
		playerTurnTutorial.skipPlayerStartTurn = true;
	}

	private IEnumerator SetupSceneCoroutine()
	{
		yield return InvokeAlternatives.WaitForFrames(3);
		SetupPlayerTutorialDice();
	}

	private void SetupCorruptedAntiquarian()
	{
		currentBattle.CorruptedAnimals = new CorruptedAnimalData[1] { corruptedAntiquarianCorruptedAnimalData };
		OnPopulateEnemies.Raise();
		Transform corruptedAntiquarianTransform = currentCorruptedAnimals.activeCorruptedAnimals.First().transform;
		corruptedAntiquarianTransform.position = singleEnemyPosition;
		corruptedAntiquarianTransform.position += Vector3.right * 10f;
		corruptedAntiquarianTransform.GetComponent<SpriteControl>().SkeletonTransform.position = corruptedAntiquarianTransform.position;
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.5f, delegate
		{
			corruptedAntiquarianTransform.gameObject.SetActive(value: false);
		});
	}

	private void SetupPlayerTutorialDice()
	{
		ReferenceSingleton<AssetsReference>.Instance.DrawPool.InventoryItems.Clear();
		for (int i = 0; i < tutorialDiceInventoryItems.Count; i++)
		{
			InventoryItem item = new InventoryItem(tutorialDiceInventoryItems[i].dice, tutorialDiceInventoryItems[i].amount);
			ReferenceSingleton<AssetsReference>.Instance.DrawPool.InventoryItems.Add(item);
		}
		ReferenceSingleton<AssetsReference>.Instance.DrawPool.UpdateDicePoolText();
	}

	public void SetupPlayerTutorialDiceSecondBattle()
	{
		ReferenceSingleton<AssetsReference>.Instance.DrawPool.InventoryItems.Clear();
		for (int i = 0; i < tutorialDiceSecondBattleInventoryItems.Count; i++)
		{
			InventoryItem item = new InventoryItem(tutorialDiceSecondBattleInventoryItems[i].dice, tutorialDiceSecondBattleInventoryItems[i].amount);
			ReferenceSingleton<AssetsReference>.Instance.DrawPool.InventoryItems.Add(item);
		}
	}
}
